    const ctlOffN = Object.assign({}, Pn.dut.ctl, { res: Object.assign({}, RSn, { on: false }) });
    const linN = 20 * Math.log10(ENG.cabs(ENG.loopModel(Pn.dut.el, ctlOffN, Pn.dut.gyro, Pn.dut.cur, Pn.dut.el.J).drr(2 * Math.PI * vn.fn)));
    add('Sürtünme DRR\'ı genliğe bağlı yapar', `Doğrusal model f_n = ${fnTxt.replace('.', ',')} Hz'de ${fmt(linN, 1).replace('.', ',').replace('-', '−')} dB verir; ${String(vn.amp_deg).replace('.', ',')}° gerçek VIV genliğinde sürtünme yön değişimleri bunu bozar (T2.2, dar bant kapalı: ${off22 ? off22.split('·')[0].trim() : '—'}). T2.1 süpürmesi hexapod erişimiyle (f_n'de ≈ ${fmt(ENG.derive(Pn).reach(vn.fn), 2).replace('.', ',')}°) koşulduğu için aynı DUT'u iyimser gösterir; kabulü gerçek genlikteki dwell belirler.`, 'T2.1 · T2.2 · B2-01');
    // v13.3 (kullanıcı kararları): kütle oranı ve mast başı ötelemesi
