  // FOG gecikmesi
  const G = P0.dut.gyro, Pa = JSON.parse(JSON.stringify(P0)), Pb = JSON.parse(JSON.stringify(P0)); Pa.dut.gyro.lat_ms = 0; Pb.dut.gyro.lat_ms = 1;
